insert into public.fatwas (number, slug, title, question, answer, category_id, source, tags, published) values
  (1001, 'حكم-نسيان-التشهد-الاول', 'حكم نسيان التشهد الأول في الصلاة', 'قمت من الركعة الثانية ناسيًا التشهد الأول، فماذا يلزمني؟ وهل تبطل صلاتي؟', 'التشهد الأول من واجبات الصلاة، فمن تركه ناسيًا ولم يستتم قائمًا رجع وأتى به، ومن استتم قائمًا مضى في صلاته ولم يرجع، ويجبر ذلك بسجود السهو قبل السلام. والصلاة صحيحة على كل حال، ولا تبطل بترك الواجب سهوًا.', (select id from public.categories where slug = 'salah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'سجود السهو, واجبات الصلاة, التشهد', true),
  (1002, 'قضاء-الصيام-عن-الميت', 'قضاء الصيام عن الميت', 'توفيت والدتي وعليها أيام من رمضان لم تقضها لعذر المرض، فهل نصوم عنها؟', 'من مات وعليه صيام واجب تمكّن من قضائه ولم يقضِ، صام عنه وليّه، لحديث: «من مات وعليه صيام صام عنه وليه». أما من استمر به المرض حتى مات ولم يتمكن من القضاء فلا شيء عليه ولا على أهله، لأن التكليف مرتفع بعجزه.', (select id from public.categories where slug = 'siyam'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'قضاء الصيام, الميت, الكفارة', true),
  (1003, 'زكاة-الذهب-المستعمل', 'زكاة الذهب المُعدّ للاستعمال', 'عندي ذهب ألبسه ولا أتاجر فيه، فهل تجب فيه الزكاة؟', 'المسألة خلافية بين أهل العلم، والأحوط أن تُخرج زكاته إذا بلغ النصاب وحال عليه الحول، والنصاب خمسة وثمانون جرامًا من الذهب، والمقدار ربع العشر (2.5%). ومن أخذ بقول من لا يوجب الزكاة في حلي الاستعمال فله سلف من أهل العلم، والأحوط للذمة الإخراج.', (select id from public.categories where slug = 'zakah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'زكاة الذهب, الحلي, النصاب', true),
  (1004, 'الوضوء-من-مس-الفرج', 'هل ينتقض الوضوء بمس الفرج؟', 'هل يجب الوضوء على من مسّ فرجه بيده؟', 'ذهب جمهور أهل العلم إلى انتقاض الوضوء بمس الفرج بلا حائل، لحديث: «من مسّ ذكره فليتوضأ». وذهب آخرون إلى أن الأمر للاستحباب. والأحوط الوضوء خروجًا من الخلاف، لا سيما إذا كان المسّ بشهوة.', (select id from public.categories where slug = 'taharah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'نواقض الوضوء, الطهارة', true),
  (1005, 'بر-الوالدين-بعد-موتهما', 'كيف أبَرّ والديّ بعد موتهما؟', 'توفي والداي، فما الأعمال التي تصلهما وأبرّهما بها؟', 'يصلهما الدعاء والاستغفار لهما، وإنفاذ عهدهما، وصلة أرحامهما، وإكرام صديقهما، والصدقة عنهما، وقضاء دَينهما، والحج والعمرة عنهما. وأعظم ذلك دوام الدعاء لهما، فإن العبد ترفع درجته بدعاء ولده له.', (select id from public.categories where slug = 'usrah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'بر الوالدين, الدعاء, الصدقة', true),
  (1006, 'حكم-التعامل-بالبنوك-الربوية', 'حكم إيداع المال في البنوك بفائدة', 'ما حكم وضع المال في البنك مقابل فائدة شهرية؟', 'الفائدة المشروطة على القرض ربا محرّم، لقوله تعالى: ﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾. ومن اضطر لحفظ ماله في بنك فليودعه في حساب جارٍ بلا فوائد، ومن أخذ فوائد سابقة تخلّص منها بصرفها في وجوه النفع العام دون احتساب أجر.', (select id from public.categories where slug = 'muamalat'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'الربا, البنوك, الفوائد', true),
  (1007, 'معنى-لا-اله-الا-الله', 'معنى شهادة أن لا إله إلا الله', 'ما معنى كلمة التوحيد؟ وما شروطها؟', 'معناها: لا معبود بحق إلا الله، فهي نفي وإثبات؛ نفي العبادة عن كل ما سوى الله، وإثباتها لله وحده. ولها شروط ذكرها أهل العلم: العلم، واليقين، والقبول، والانقياد، والصدق، والإخلاص، والمحبة، والكفر بما يُعبد من دون الله.', (select id from public.categories where slug = 'aqeedah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'التوحيد, الشهادتان, العقيدة', true),
  (1008, 'العمرة-عن-الغير', 'العمرة عن الوالد العاجز', 'والدي كبير في السن ولا يستطيع السفر، فهل أعتمر عنه؟', 'نعم، تصح النيابة في الحج والعمرة عن العاجز عجزًا لا يُرجى زواله، كالكبير والمريض مرضًا مزمنًا. ويشترط أن يكون النائب قد حج عن نفسه أولًا، لحديث شبرمة: «حُجّ عن نفسك ثم حج عن شبرمة».', (select id from public.categories where slug = 'hajj'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'النيابة في الحج, العمرة, العجز', true),
  (1009, 'اداب-طلب-العلم', 'من آداب طالب العلم', 'ما النصيحة لمن أراد أن يبدأ في طلب العلم الشرعي؟', 'أول ذلك إخلاص النية لله، ثم التدرّج في الطلب بالبدء بصغار العلم قبل كباره، ولزوم عالم ربّاني يأخذ عنه، والعناية بحفظ القرآن وفهمه، والعمل بما يعلم، وحسن الخلق والتواضع، والصبر على طول الطريق.', (select id from public.categories where slug = 'adab'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'طلب العلم, الإخلاص, الأدب', true),
  (1010, 'احكام-قراءة-القران-للحائض', 'قراءة القرآن للحائض', 'هل يجوز للحائض أن تقرأ القرآن من حفظها أو من المصحف؟', 'ذهب جمع من أهل العلم إلى جواز قراءتها من حفظها؛ إذ لم يثبت نص صريح صحيح في المنع، وحاجتها إلى المراجعة والتعلم قائمة. وأما مسّ المصحف فالجمهور على المنع إلا بحائل، ولها أن تقرأ من الجوال أو الحاسوب لأنه ليس بمصحف.', (select id from public.categories where slug = 'tafsir'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'الحائض, قراءة القرآن, مس المصحف', true),
  (1011, 'الجمع-بين-الصلاتين-للمسافر', 'الجمع والقصر للمسافر', 'متى يجوز للمسافر أن يجمع بين الصلاتين ويقصر؟', 'القصر سنّة المسافر ما دام مسافرًا، فيصلي الرباعية ركعتين. وأما الجمع فرخصة عند الحاجة والمشقة كالسير في الطريق، فإن نزل في مكان واستراح فالأفضل ترك الجمع مع بقاء القصر.', (select id from public.categories where slug = 'salah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'السفر, القصر, الجمع', true),
  (1012, 'زكاة-الفطر-مقدارها-ووقتها', 'مقدار زكاة الفطر ووقت إخراجها', 'كم مقدار زكاة الفطر؟ ومتى تُخرج؟ وهل تُخرج نقدًا؟', 'مقدارها صاع من طعام أهل البلد، والصاع نحو ثلاثة كيلوجرامات تقريبًا. ووقت إخراجها قبل صلاة العيد، ويجوز تقديمها بيوم أو يومين. والأصل إخراجها طعامًا كما جاءت به السنة، ومن أخرجها نقدًا مقلّدًا لمن أجاز ذلك من أهل العلم فلا يُنكر عليه.', (select id from public.categories where slug = 'zakah'), 'مثال توضيحي — يُستبدل بالمصدر الموثّق من لوحة التحكم', 'زكاة الفطر, الصاع, العيد', true)
insert into public.books (title, description, year, publisher, volumes, sort_order) values
  ('الصحيح المسند من أسباب النزول', 'جمعٌ لما صحّ من أسباب نزول آيات القرآن الكريم مع التخريج والحكم على الأسانيد.', '', '', '', 0),
  ('التسهيل لتأويل التنزيل', 'تفسير للقرآن الكريم بأسلوب الأسئلة والأجوبة، صدر في أجزاء بحسب سور القرآن.', '', '', '', 1),
  ('جامع أحكام النساء', 'موسوعة فقهية في الأحكام المتعلقة بالمرأة المسلمة مع الأدلة والترجيح.', '', '', '', 2),
  ('فقه التعامل مع الوالدين', 'رسالة في بيان حقوق الوالدين وصور البر بهما في الحياة وبعد الممات.', '', '', '', 3),
  ('مفاتيح الفقه في الدين', 'مدخل إلى مسائل الفقه بأسلوب ميسّر مع الاستدلال من الكتاب والسنة.', '', '', '', 4);
